CREATE TABLE "page_translation" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "page_translation_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"pageId" integer NOT NULL,
	"locale" "locale" NOT NULL,
	"name" text NOT NULL,
	"seoTitle" text,
	"seoDescription" text,
	"createdAt" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "page_translation_pageId_locale_unique" UNIQUE("pageId","locale"),
	CONSTRAINT "page_translation_texts_length" CHECK (char_length("page_translation"."name") BETWEEN 1 AND 60 AND char_length("page_translation"."seoTitle") <= 70 AND char_length("page_translation"."seoDescription") <= 160)
);
